import{_ as i,o as a,c as t,a as l}from"./chunks/framework.Ld7uezS_.js";const h=JSON.parse('{"title":"设施操作前置知识补强概览","description":"","frontmatter":{},"headers":[],"relativePath":"outputs/overview-2026-08-21-operation-prerequisite.md","filePath":"outputs/overview-2026-08-21-operation-prerequisite.md","lastUpdated":1787282109000}'),r={name:"outputs/overview-2026-08-21-operation-prerequisite.md"};function o(s,e,n,d,u,c){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="设施操作前置知识补强概览" tabindex="-1">设施操作前置知识补强概览 <a class="header-anchor" href="#设施操作前置知识补强概览" aria-label="Permalink to &quot;设施操作前置知识补强概览&quot;">​</a></h1><h2 id="用户反馈" tabindex="-1">用户反馈 <a class="header-anchor" href="#用户反馈" aria-label="Permalink to &quot;用户反馈&quot;">​</a></h2><p>原页面写了“确认任务和对象”，但没有先教零基础学习者如何识别任务、对象、区域、操作目的和完成标准。</p><h2 id="本次补强" tabindex="-1">本次补强 <a class="header-anchor" href="#本次补强" aria-label="Permalink to &quot;本次补强&quot;">​</a></h2><ul><li>将“确认任务和对象”扩展为可学习课程，而不是一句操作要求；</li><li>解释五类任务：查询/确认、操作/控制、测试/验证、恢复/收口、报告/交接；</li><li>解释四层对象：输入对象、控制对象、执行对象、反馈对象；</li><li>解释区域定位：建筑、楼层、房间、防火分区、报警区域、设备地址、设备位置和水系统测试点；</li><li>增加“操作目的”和“完成标准”的区别；</li><li>增加“位置—对象—动作—目的—预期—恢复”任务复述模板；</li><li>以排烟风机联动为例，完整演示从任务拆解到恢复记录的过程；</li><li>在消防泵训练题 S02 中加入对象层级和任务拆解解释，避免只展示步骤；</li><li>同步综合课程、术语表、零基础导学、训练总览、标准映射、覆盖矩阵和项目概览。</li></ul><h2 id="校验" tabindex="-1">校验 <a class="header-anchor" href="#校验" aria-label="Permalink to &quot;校验&quot;">​</a></h2><ul><li><code>git diff --check</code>：通过；</li><li>理论题卡：T01-T39，共 39 张，无缺号；</li><li>技能题卡：S01-S49，共 49 张，无缺号；</li><li>未运行 VitePress 构建，保留项目既有构建问题不与本次内容变更混合。</li></ul>',7)])])}const _=i(r,[["render",o]]);export{h as __pageData,_ as default};
